@namespace sv_18e077f0e3544b219afb923f1d12f7d7.Components.Chat

<aside class="channel-sidebar">
    <div class="sidebar-header">
        <h2>Channels</h2>
    </div>
    <nav class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelect="OnSelectChannel" />
        }
    </nav>
</aside>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnSelectChannel { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    background: #1e1e2e;
    color: #ccc;
    height: 100%;
    overflow: hidden;
}

