arguments.file_text:
.chat-layout {
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_18e077f0e3544b219afb923f1d12f7d7.Components.Chat
@using sv_18e077f0e3544b219afb923f1d12f7d7.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannel?.Id"
                        OnSelectChannel="SelectChannelAsync" />
    </div>

    <div class="main-panel">
        <MessageArea CurrentChannel="selectedChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingOlder="isLoadingOlder"
                     OnLoadOlder="LoadOlderMessagesAsync"
                     OnOpenThread="OpenThreadAsync"
                     OnReact="HandleReactionAsync"
                     OnSendMessage="SendMessageAsync" />
    </div>

    @if (isThreadOpen && threadRootMessage is not null)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReplyAsync"
                         OnReact="HandleReactionAsync" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = [];
    private bool isLoadingOlder;
    private int messageSkip;
    private const int PageSize = 30;
    private bool hasMoreMessages = true;

    // Thread state
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        if (selectedChannel is null) return;

        messageSkip = 0;
        hasMoreMessages = true;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channelId);
        BuildThreadSummaries();

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (selectedChannel is null || isLoadingOlder || !hasMoreMessages) return;

        isLoadingOlder = true;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messageSkip, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, older);
        messageSkip += older.Count;
        BuildThreadSummaries();
        isLoadingOlder = false;
    }

    private async Task SendMessageAsync(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary in main view
        if (threadSummaries.ContainsKey(threadRootMessage.Id))
        {
            var existing = threadSummaries[threadRootMessage.Id];
            threadSummaries[threadRootMessage.Id] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
